def _a_milk_pump_question(understood):
    """The pumping room's own question, with the machine pump kept out of it."""
    return _not_a_machine_pump(understood) and _a_milk_question(understood)


def _a_milk_question(understood):
    """False when the line says nothing about milk: "back at work" is then not this answer."""
    if not isinstance(understood, dict):
        return False
    words = set()
    for part in ("clean", "text", "norm", "words"):
        value = understood.get(part)
        if isinstance(value, (list, tuple, set, frozenset)):
            words |= {str(word).lower() for word in value}
        else:
            words |= set(re.findall(r"[a-z']+", str(value or "").lower()))
    return bool(words & _MILK_SAID)


def _a_caffeine_drink_was_named(understood):
    """The line names a drink, so the caffeine limit is its answer and a plate of food is not."""
    if not isinstance(understood, dict):
        return False
    words = set()
    for part in ("clean", "text", "norm"):
        words |= set(re.findall(r"[a-z']+", str(understood.get(part) or "").lower()))
    return bool(words & _CAFFEINE_SAID)


# The words that make a line a feeding mother's own question. Shared by the two rows below.
# Not "feeding my baby": that is the one phrase in the tuple with a baby in it, and a line that
# names the baby is the weaning question ("should i avoid peanuts while feeding my baby" wants
# the six-months smear, not "Yes - eat them" about her own plate).
_FEEDING = ("breastfeeding", "breast feeding", "breastfeed", "breast-fed", "nursing", "nurse",
            "lactating", "chestfeeding", "chest feeding", "while feeding", "still feeding")


# The words that ask for something to cook rather than for help with the eating.
_COOK_ASK = frozenset(("cook", "cooking", "make", "making", "dinner", "tea", "supper", "lunch",
                       "meal", "meals", "recipe", "recipes", "idea", "ideas", "suggest",
                       "suggestion", "feed"))


# What a parent adds to the verb: "what if he just refuses dinner", "she still refuses food".
# The adverb sits between the pronoun and the verb, and a key phrase is not read across a
# breather ("my phone just died" style relaxations are for avoid lists only, because loosening a
# key would let a row answer a line it does not fit), so each shape is written out. Without them
# the fussy-eater row stood down on "what if she just refuses dinner" and, the politeness card
# having stood down for a child, the turn was a shrug.
_REFUSAL_WITH_AN_ADVERB = tuple(
    "%s %s refuses %s" % (who, how, what)
    for who, poss in (("he", "his"), ("she", "her"))
    for how in ("just", "still", "now")
    for what in ("dinner", "%s dinner" % poss, "food", "%s food" % poss, "meals", "the meal"))


def _picky_eater(memory, understood):
    """The fussy-eating answer, or None when the line is a dinner with one food ruled out.

    "my son wont eat onions what can i cook" is not the fussy-eating worry this entry was written
    for: it names the one food to leave out and asks what to cook, and the answer to that is the
    kitchen's swap for the onion, not advice about trying new foods. A worry names no such food
    ("my four year old will only eat bread and cheese", "my toddler wont eat vegetables") and the
    fussy answer is still the one it needs.
    """
    from . import cooking  # imported here: the kitchen reads this table's food words
    text = str(understood.get("clean") or understood.get("norm_text") or "") \
        if isinstance(understood, dict) else ""
    words = set(str(word) for word in (understood.get("words") or ())) \
        if isinstance(understood, dict) else set()
    if _COOK_ASK & words and cooking._refused_foods(text):
        return None
    return PICKY_EATER


